import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './index.css';

// Componentes Icones (pode remover se não quiser usar ícones e colocar texto)
const HeartIcon = () => <span style={{fontSize:'1.2rem'}}>♥</span>;
const CommentIcon = () => <span style={{fontSize:'1.2rem'}}>💬</span>;
const GraphIcon = () => <span style={{fontSize:'1.2rem', color: '#666'}}>📊</span>;

function App() {
  const [atividades, setAtividades] = useState([]);
  const [paginaAtual, setPaginaAtual] = useState(1);
  const [usuario, setUsuario] = useState(null);
  
  const [mostrarModal, setMostrarModal] = useState(false);
  const [isCadastro, setIsCadastro] = useState(false);
  const [email, setEmail] = useState('');
  const [senha, setSenha] = useState('');
  const [erro, setErro] = useState('');

  const ITENS_POR_PAGINA = 4;

  useEffect(() => {
    carregarAtividades();
  }, []);

  const carregarAtividades = async () => {
    try {
      const res = await axios.get('http://localhost:3000/atividades');
      // Adicionando dados mockados para o design (Usuário e Calorias) que não vêm da API padrão
      const atividadesComDesign = res.data.map((item, index) => ({
        ...item,
        usuarioNome: index % 2 === 0 ? "Usuário_01" : "Usuário_02",
        usuarioAvatar: index % 2 === 0 ? "https://i.pravatar.cc/150?u=a042581f4e29026704d" : "https://i.pravatar.cc/150?u=a042581f4e29026704e",
        calorias: 350, // fixo para o design
        data: index % 2 === 0 ? "18:30 - 12/08/2024" : "20:40 - 15/08/2024", // fixo para o design
        comentarios_count: 4 // fixo para o design
      }));
      setAtividades(atividadesComDesign);
    } catch (err) {
      console.error(err);
    }
  };

  const handleAuth = async (e) => {
    e.preventDefault();
    setErro('');
    const endpoint = isCadastro ? '/registrar' : '/login';
    
    try {
      const res = await axios.post(`http://localhost:3000${endpoint}`, { email, senha });
      setUsuario(res.data);
      setMostrarModal(false);
      setEmail('');
      setSenha('');
    } catch (err) {
      setErro(err.response?.data?.error || 'Erro na requisição.');
    }
  };

  const handleCurtir = async (id) => {
    if (!usuario) {
      setMostrarModal(true);
      return;
    }

    try {
      await axios.post(`http://localhost:3000/atividades/${id}/curtir`, {
        usuarioId: usuario.id
      });
      carregarAtividades();
    } catch (err) {
      alert(err.response?.data?.error || 'Erro ao curtir.');
    }
  };

  const indiceUltimo = paginaAtual * ITENS_POR_PAGINA;
  const atividadesPaginadas = atividades.slice(indiceUltimo - ITENS_POR_PAGINA, indiceUltimo);
  const totalPaginas = Math.ceil(atividades.length / ITENS_POR_PAGINA);

  return (
    <div className="layout-saep">
      {/* Barra Lateral */}
      <aside className="sidebar">
        <div className="sidebar-header">
          <img src="https://via.placeholder.com/100" alt="Logo SAEP Saúde" className="sidebar-logo" />
          <h1 className="sidebar-title">SAEPSaúde</h1>
        </div>
        <div className="sidebar-stats">
          <div className="stat-item">
            <span className="stat-value">3</span>
            <span className="stat-label">Qtd. Atividades</span>
          </div>
          <div className="stat-item">
            <span className="stat-value">100</span>
            <span className="stat-label">Qtd. Calorias</span>
          </div>
        </div>
        <div className="sidebar-menu">
          <a href="#" className="menu-item active">
            <GraphIcon /> Atividade
          </a>
        </div>
        <div className="sidebar-footer">
          <span className="footer-title">SAEPSaúde</span>
          <div className="footer-social">
            {/* Adicione links de redes sociais se desejar */}
            <span>[Social Icons]</span>
          </div>
          <span className="footer-copyright">Copyright - 2025/2026</span>
        </div>
      </aside>

      {/* Conteúdo Principal */}
      <main className="main-content">
        <header className="content-header">
          {usuario ? (
            <div className="user-info">
              <span>{usuario.email}</span>
              <button className="btn btn-secondary btn-sm" onClick={() => setUsuario(null)}>Sair</button>
            </div>
          ) : (
            <button className="btn btn-primary btn-sm" onClick={() => setMostrarModal(true)}>Login</button>
          )}
        </header>

        {/* Barra de Filtros */}
        <div className="filter-bar">
          <button className="filter-item active">Corrida</button>
          <button className="filter-item">Caminhada</button>
          <button className="filter-item">Trilha</button>
        </div>

        {/* Feed de Atividades */}
        <div className="atividades-feed">
          {atividadesPaginadas.map((item) => (
            <div key={item.id} className="atividade-card">
              <div className="card-left">
                <img src={item.usuarioAvatar} alt="Avatar Usuário" className="user-avatar" />
                <div className="user-name">{item.usuarioNome}</div>
              </div>
              <div className="card-center">
                <h3 className="atividade-tipo">{item.tipo}</h3>
                <div className="atividade-meta-data">
                  <span>{(item.distancia_m / 1000).toFixed(1)} km</span>
                  <span className="meta-label">Distância</span>
                </div>
                <div className="atividade-meta-data">
                  <span>{item.duracao_min} min</span>
                  <span className="meta-label">Duração</span>
                </div>
                <div className="atividade-meta-data">
                  <span>{item.calorias}</span>
                  <span className="meta-label">Calorias</span>
                </div>
              </div>
              <div className="card-right">
                <div className="atividade-data">{item.data}</div>
                <div className="card-actions">
                  <div className="action-item" onClick={() => handleCurtir(item.id)}>
                    <HeartIcon /> {item.curtidas_count}
                  </div>
                  <div className="action-item">
                    <CommentIcon /> {item.comentarios_count}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Paginação */}
        {totalPaginas > 1 && (
          <div className="pagination">
            <button className="page-btn disabled" disabled={paginaAtual === 1} onClick={() => setPaginaAtual(p => p - 1)}>Anterior</button>
            <div className="page-numbers">
                <button className={`page-number ${paginaAtual === 1 ? 'active' : ''}`} onClick={() => setPaginaAtual(1)}>1</button>
                {totalPaginas >= 2 && <button className={`page-number ${paginaAtual === 2 ? 'active' : ''}`} onClick={() => setPaginaAtual(2)}>2</button>}
                {totalPaginas >= 3 && <button className={`page-number ${paginaAtual === 3 ? 'active' : ''}`} onClick={() => setPaginaAtual(3)}>3</button>}
            </div>
            <button className="page-btn" disabled={paginaAtual === totalPaginas} onClick={() => setPaginaAtual(p => p + 1)}>Próximo</button>
          </div>
        )}
      </main>

      {/* Modal de Login/Cadastro (inalterado em lógica, apenas ajustado para o novo layout) */}
      {mostrarModal && (
        <div className="modal-overlay">
          <div className="modal">
            <h2>{isCadastro ? 'Criar Conta' : 'Acessar Conta'}</h2>
            {erro && <p className="error-msg">{erro}</p>}
            <form onSubmit={handleAuth}>
              <input className="input" type="email" placeholder="Seu e-mail" value={email} onChange={e => setEmail(e.target.value)} required />
              <input className="input" type="password" placeholder="Sua senha" value={senha} onChange={e => setSenha(e.target.value)} required />
              <button className="btn btn-primary" type="submit" style={{ width: '100%', marginBottom: '8px' }}>
                {isCadastro ? 'Cadastrar' : 'Entrar'}
              </button>
            </form>
            <button className="btn btn-secondary" style={{ width: '100%' }} onClick={() => { setIsCadastro(!isCadastro); setErro(''); }}>
              {isCadastro ? 'Já tenho uma conta' : 'Criar nova conta'}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
